def comps(g,bg=None):
    import numpy as np
    g=np.array(g); seen=np.zeros_like(g,bool); out=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j]==bg and seen[i,j]: continue
            if g[i,j]!=bg and seen[i,j]: continue
            st=[(i,j)]; seen[i,j]=True
            cells=[]
            while st:
                r,c=st.pop(); cells.append((r,c))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<g.shape[0] and 0<=cc<g.shape[1] and not seen[rr,cc] and g[rr,cc]!=bg:
                            seen[rr,cc]=True; st.append((rr,cc))
            out.append(cells)
    return out
